import { branchById } from '../config/branches.js';
import { composeNotice } from '../notices/compose.js';
import { pickupDeadline } from './pickup-shelf.js';

/** Returns the notice that tells a member their hold is ready to collect. */
export function holdReadyNotice(store, hold) {
  const member = store.getMember(hold.memberId);
  const item = store.getItem(hold.itemId);
  return composeNotice('holdReady', {
    member,
    values: {
      title: item.title,
      branch: branchById(hold.pickupBranchId).name,
      deadline: pickupDeadline(hold),
    },
  });
}
import { branchById } from '../config/branches.js';
import { addDays, nextOpenDay } from '../helpers/dates.js';

/** How many days a ready hold waits on the pickup shelf. */
export const PICKUP_DAYS = 10;

/** Returns the last day a ready hold can be collected at its pickup branch. */
export function pickupDeadline(hold) {
  return nextOpenDay(branchById(hold.pickupBranchId), addDays(hold.readyOn, PICKUP_DAYS));
}

/** Marks every ready hold whose pickup deadline has passed by `today` as expired, and returns them. */
export function expireUncollectedHolds(store, today) {
  const expired = [];
  for (const hold of store.listAllHolds()) {
    if (hold.status === 'ready' && pickupDeadline(hold) < today) {
      expired.push(store.saveHold({ ...hold, status: 'expired' }));
    }
  }
  return expired;
}
/** Puts a member in the queue for an item. Returns { ok: true, hold } or { ok: false, reason }. */
export function placeHold(store, { itemId, memberId, pickupBranchId, today }) {
  if (store.getItem(itemId) === undefined) return { ok: false, reason: 'unknown-item' };
  if (holdQueue(store, itemId).some((hold) => hold.memberId === memberId)) {
    return { ok: false, reason: 'already-queued' };
  }
  const hold = store.saveHold({
    itemId,
    memberId,
    pickupBranchId,
    placedOn: today,
    status: 'waiting',
    readyOn: null,
  });
  return { ok: true, hold };
}

/** Returns the holds still waiting or ready for an item, the first placed first. */
export function holdQueue(store, itemId) {
  return store
    .listHolds(itemId)
    .filter((hold) => hold.status === 'waiting' || hold.status === 'ready')
    .sort(
      (first, second) => first.placedOn.localeCompare(second.placedOn) || first.id.localeCompare(second.id),
    );
}

/**
 * Makes the first waiting hold for an item ready for pickup from today, and returns it; returns
 * null when nobody is waiting.
 */
export function fulfilNextHold(store, itemId, today) {
  const next = holdQueue(store, itemId).find((hold) => hold.status === 'waiting');
  if (next === undefined) return null;
  return store.saveHold({ ...next, status: 'ready', readyOn: today });
}
import assert from 'node:assert/strict';
import test from 'node:test';
import { expireUncollectedHolds, pickupDeadline } from '../lib/holds/pickup-shelf.js';
import { fulfilNextHold, holdQueue, placeHold } from '../lib/holds/queue.js';
import { ADA, BEN, BOOK, CY, sampleStore, TODAY } from './sample-library.js';

function hold({ id, member, placedOn, status = 'waiting', readyOn = null }) {
  return { id, itemId: BOOK.id, memberId: member.id, pickupBranchId: 'central', placedOn, status, readyOn };
}

test('places a hold at the end of the queue', () => {
  const store = sampleStore({ holds: [hold({ id: 'hold_a', member: BEN, placedOn: '2026-11-01' })] });
  const result = placeHold(store, {
    itemId: BOOK.id,
    memberId: ADA.id,
    pickupBranchId: 'central',
    today: TODAY,
  });
  assert.equal(result.ok, true);
  assert.deepEqual(
    holdQueue(store, BOOK.id).map((queued) => queued.memberId),
    [BEN.id, ADA.id],
  );
});

test('refuses a second hold of the same member on an item', () => {
  const store = sampleStore({ holds: [hold({ id: 'hold_a', member: ADA, placedOn: '2026-11-01' })] });
  const result = placeHold(store, {
    itemId: BOOK.id,
    memberId: ADA.id,
    pickupBranchId: 'central',
    today: TODAY,
  });
  assert.deepEqual(result, { ok: false, reason: 'already-queued' });
});

test('readies the hold placed first', () => {
  const store = sampleStore({
    holds: [
      hold({ id: 'hold_b', member: ADA, placedOn: '2026-11-03' }),
      hold({ id: 'hold_a', member: BEN, placedOn: '2026-11-01' }),
    ],
  });
  const ready = fulfilNextHold(store, BOOK.id, TODAY);
  assert.equal(ready.memberId, BEN.id);
  assert.equal(ready.readyOn, TODAY);
});

test('a ready hold can be collected for 10 days, until the branch next opens', () => {
  assert.equal(
    pickupDeadline(hold({ id: 'h', member: ADA, placedOn: '2026-11-01', readyOn: '2026-11-19' })),
    '2026-11-30',
  );
  assert.equal(
    pickupDeadline(hold({ id: 'h', member: ADA, placedOn: '2026-11-01', readyOn: '2026-11-15' })),
    '2026-11-25',
  );
});

test('expires the ready holds that nobody collected in time', () => {
  const store = sampleStore({
    holds: [
      hold({ id: 'hold_a', member: BEN, placedOn: '2026-10-01', status: 'ready', readyOn: '2026-11-02' }),
      hold({ id: 'hold_b', member: CY, placedOn: '2026-10-02', status: 'ready', readyOn: '2026-11-24' }),
    ],
  });
  const expired = expireUncollectedHolds(store, TODAY);
  assert.deepEqual(
    expired.map((expiredHold) => expiredHold.id),
    ['hold_a'],
  );
  assert.equal(store.listHolds(BOOK.id).find((stored) => stored.id === 'hold_b').status, 'ready');
});
/** How long each format is lent for, in days, and how many times a loan of it may be renewed. */
export const LOAN_RULES = {
  book: { loanDays: 21, maxRenewals: 2 },
  dvd: { loanDays: 7, maxRenewals: 1 },
  magazine: { loanDays: 7, maxRenewals: 0 },
  laptop: { loanDays: 1, maxRenewals: 0 },
};

/** How many items a member of each type may have on loan at once. */
export const MAX_ITEMS_ON_LOAN = { adult: 30, junior: 10, staff: 50 };

/** How many years a new or renewed library card is valid, by member type. */
export const CARD_YEARS = { adult: 3, junior: 1, staff: 3 };
